import sys

def main():
    data = sys.stdin.buffer.read().split()
    n = int(data[0])
    strings = [x.decode() for x in data[1:1 + n]]
    max_len = max(map(len, strings), default=0)

    prefixes = [set() for _ in range(max_len + 1)]
    suffixes = [set() for _ in range(max_len + 1)]
    substrings = [set() for _ in range(max_len + 1)]

    for s in strings:
        length = len(s)

        if s in substrings[length]:
            print(s)
            return

        for split in range(1, length):
            if s[:split] in suffixes[split] and s[split:] in prefixes[length - split]:
                print(s)
                return

        for size in range(1, length + 1):
            prefixes[size].add(s[:size])
            suffixes[size].add(s[-size:])
            for start in range(length - size + 1):
                substrings[size].add(s[start:start + size])

    print("ok")

if __name__ == "__main__":
    main()
